4	/**
5	 * Lightweight tsconfig extends walker that does NOT load the `typescript`
6	 * package. For full TypeScript-aware parsing (compilerOptions resolution,
7	 * file lists, project references, etc.) see the `@nx/js/typescript` plugin,
8	 * which uses `ts.parseJsonConfigFileContent` and a persistent cache.
9	 */
10	
11	/**
12	 * Cache of raw parsed tsconfig JSON contents, keyed by absolute file path.
13	 * `null` indicates a file that doesn't exist or failed to parse.
14	 *
15	 * Instantiate with `new Map()` and reuse across `walkTsconfigExtendsChain`
16	 * calls within one `createNodes` invocation to dedupe file reads when many
17	 * starting points share parent tsconfigs.
18	 */
19	export type RawTsconfigJsonCache = Map<string, unknown | null>;
20	
21	/**
22	 * Walks the `extends` chain of a tsconfig, invoking `visit` for each unique
23	 * reachable file (entry first, then recursively). Cycle-safe. Files that
24	 * don't exist or fail to parse are silently skipped.
25	 *
26	 * When a tsconfig has multiple `extends` entries they are visited in
27	 * REVERSE order, so visitors looking for the effective value of an
28	 * inherited option see the highest-precedence entries first and can
29	 * return `'stop'` to abort the traversal. Visitors that want to collect
30	 * every reachable file should always return `'continue'`.
31	 *
32	 * @param entryAbsolutePath Absolute, canonical path of the tsconfig to
33	 *   start from. Pass through `path.resolve()` if unsure.
34	 * @param visit Invoked once per unique reachable tsconfig.
35	 * @param options.jsonCache Optional shared cache of parsed tsconfig
36	 *   contents. When omitted, the walker uses a fresh internal cache.
37	 */
38	export function walkTsconfigExtendsChain(
39	  entryAbsolutePath: string,
40	  visit: (absolutePath: string, rawJson: unknown) => 'continue' | 'stop',
41	  options?: { jsonCache?: RawTsconfigJsonCache }
42	): void {
43	  const jsonCache: RawTsconfigJsonCache = options?.jsonCache ?? new Map();
44	  walk(entryAbsolutePath, visit, jsonCache, new Set());
45	}
46	
47	function walk(
48	  absolutePath: string,
49	  visit: (absolutePath: string, rawJson: unknown) => 'continue' | 'stop',
50	  jsonCache: RawTsconfigJsonCache,
51	  visited: Set<string>
52	): 'continue' | 'stop' {
53	  if (visited.has(absolutePath)) return 'continue';
54	  visited.add(absolutePath);
55	
56	  const json = readCachedJson(absolutePath, jsonCache);
57	  if (json === null) return 'continue';
58	
59	  if (visit(absolutePath, json) === 'stop') return 'stop';
60	
61	  const extendsField = (json as { extends?: unknown }).extends;
62	  if (!extendsField) return 'continue';
63	  const extendsList = Array.isArray(extendsField)
64	    ? extendsField
65	    : [extendsField];
66	
67	  // Last entry wins per TypeScript precedence; walk in reverse so
68	  // precedence-aware visitors see the highest-precedence entries first.
69	  const fromDir = dirname(absolutePath);
70	  for (let i = extendsList.length - 1; i >= 0; i--) {
71	    const ext = extendsList[i];
72	    if (typeof ext !== 'string' || !ext) continue;
73	    const childPath = resolveExtendsPath(ext, fromDir);
74	    if (childPath === null) continue;
75	    if (walk(childPath, visit, jsonCache, visited) === 'stop') return 'stop';
76	  }
77	
78	  return 'continue';
79	}
