s &&\n        Number.isInteger(args.parallel) &&\n        runningTasks.length < args.parallel\n      ) {\n        // Don't bother with this optimization if there are fewer tasks remaining than rows required\n        if (remainingTasks >= args.parallel) {\n          for (let i = runningTasks.length; i < args.parallel; i++) {\n            additionalFooterRows.push('');\n          }\n        }\n      }\n    }\n\n    if (totalSuccessfulTasks > 0 || totalFailedTasks > 0) {\n      additionalFooterRows.push('');\n    }\n\n    if (totalSuccessfulTasks > 0) {\n      additionalFooterRows.push(\n        `${LEFT_PAD}${output.colors.green(\n          figures.tick\n        )}${SPACER}${totalSuccessfulTasks}${`/${totalCompletedTasks}`} succeeded ${output.dim(\n          `[${totalCachedTasks} read from cache]`\n        )}`\n      );\n    }\n\n    if (totalFailedTasks > 0) {\n      additionalFooterRows.push(\n        `${LEFT_PAD}${output.colors.red(\n          figures.cross\n        )}${SPACER}${totalFailedTasks}${`/${totalCompletedTasks}`} failed`\n      );\n    }\n\n    moveCursorToStartOfPinnedFooter();\n\n    if (additionalFooterRows.length > 1) {\n      const text = `Running ${formatTargetsAndProjects(\n        projectNames,\n        targets,\n        tasks\n      )}`;\n      const taskOverridesRows = [];\n      const filteredOverrides = Object.entries(overrides).filter(\n        // Don't print the data passed through from the version subcommand to the publish executor options, it could be quite large and it's an implementation detail.\n        ([flag]) => flag !== 'nxReleaseVersionData'\n      );\n      if (filteredOverrides.length > 0) {\n        taskOverridesRows.push('');\n        taskOverridesRows.push(\n          `${EXTENDED_LEFT_PAD}${pc.dim(pc.cyan('With additional flags:'))}`\n        );\n        filteredOverrides\n          .map(([flag, value]) =>\n            pc.dim(pc.cyan(formatFlags(EXTENDED_LEFT_PAD, flag, value)))\n          )\n          .forEach((arg) => taskOverridesRows.push(arg));\n      }\n\n      const pinnedFooterLines = [\n        output.applyNxPrefix('cyan', output.colors.cyan(text)),\n        ...taskOverridesRows,\n        ...additionalFooterRows,\n      ];\n\n      // Vertical breathing room when there isn't yet any output or divider\n      if (!hasTaskOutput) {\n        pinnedFooterLines.unshift('');\n      }\n\n      renderPinnedFooter(pinnedFooterLines);\n    } else {\n      renderPinnedFooter([]);\n    }\n  };\n\n  lifeCycle.startCommand = () => {\n    if (projectNames.length <= 0) {\n      renderPinnedFooter([\n        '',\n        output.applyNxPrefix(\n          'gray',\n          `No projects with ${formatTargetsAndProjects(\n            projectNames,\n            targets,\n            tasks\n          )} were run`\n        ),\n      ]);\n      resolveRenderIsDonePromise();\n      return;\n    }\n    renderPinnedFooter([]);\n  };\n\n  lifeCycle.endCommand = () => {\n    clearRenderInterval();\n    const timeTakenText = prettyTime(process.hrtime(start));\n\n    moveCursorToStartOfPinnedFooter();\n    if (totalTasks === 0) {\n      renderPinnedFooter([output.applyNxPrefix('gray', 'No tasks were run')]);\n      resolveRenderIsDonePromise();\n      return;\n    }\n    if (totalSuccessfulTasks === totalTasks) {\n      const text = `Successfully ran ${formatTargetsAndProjects(\n        projectNames,\n        targets,\n        tasks\n      )}`;\n      const taskOverridesRows = [];\n      const filteredOverrides = Object.entries(overrides).filter(\n        // Don't print the data passed through from the version subcommand to the publish executor options, it could be quite large and it's an implementation detail.\n        ([flag]) => flag !== 'nxReleaseVersionData'\n      );\n      if (filteredOverrides.length > 0) {\n        taskOverridesRows.push('');\n        taskOverridesRows.push(\n          `${EXTENDED_LEFT_PAD}${pc.dim(pc.green('With additional flags:'))}`\n        );\n        filteredOverrides\n          