th = path.join(target, relativeFromSrcFolder);\n  if (computedPath.endsWith('.template')) {\n    computedPath = computedPath.substring(0, computedPath.length - 9);\n  }\n  Object.entries(substitutions).forEach(([propertyName, value]) => {\n    computedPath = computedPath.split(`__${propertyName}__`).join(value);\n  });\n  return computedPath;\n}\n\nfunction allFilesInDir(parent: string): string[] {\n  let res: string[] = [];\n  try {\n    readdirSync(parent).forEach((c) => {\n      const child = path.join(parent, c);\n      try {\n        const s = statSync(child);\n        if (!s.isDirectory()) {\n          res.push(child);\n        } else if (s.isDirectory()) {\n          res = [...res, ...allFilesInDir(child)];\n        }\n      } catch {}\n    });\n  } catch {}\n  return res;\n}\n"],"names":["OverwriteStrategy","generateFiles","tree","srcFolder","target","substitutions","options","overwriteStrategy","ejs","require","files","allFilesInDir","length","Error","forEach","filePath","newContent","computedPath","computePath","exists","isBinaryPath","readFileSync","template","render","filename","e","logger","error","replace","root","write","relativeFromSrcFolder","path","relative","join","endsWith","substring","Object","entries","propertyName","value","split","parent","res","readdirSync","c","child","s","statSync","isDirectory","push"],"mappings":";;;;oBAAoD;8DAC9B;kCACO;+BAEK;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;+BAKtBA;;;eAAAA;;;QAAAA;;;;+BAwCIC;;;eAAAA;;;QAAAA;;;;AAxCT,IAAA,AAAKD,2CAAAA;;;;WAAAA;;AAwCL,SAASC,cACdC,IAAU,EACVC,SAAiB,EACjBC,MAAc,EACdC,aAAmC,EACnCC,UAAgC;IAC9BC,iBAAiB;AACnB,CAAC;IAEDD,YAAY,CAAC;IACbA,QAAQC,iBAAiB;IAEzB,MAAMC,MAAMC,QAAQ;IAEpB,MAAMC,QAAQC,cAAcR;IAC5B,IAAIO,MAAME,MAAM,KAAK,GAAG;QACtB,MAAM,IAAIC,MACR,CAAC,kCAAkC,EAAEV,UAAU,+CAA+C,CAAC;IAEnG,OAAO;QACLO,MAAMI,OAAO,CAAC,CAACC;YACb,IAAIC;YACJ,MAAMC,eAAeC,YACnBf,WACAC,QACAW,UACAV;YAGF,IAAIH,KAAKiB,MAAM,CAACF,eAAe;gBAC7B,IAAIX,QAAQC,iBAAiB,qBAAqC;oBAChE;gBACF,OAAO,IACLD,QAAQC,iBAAiB,wBACzB;oBAC