  workspaceRoot,\n      projectAbsolutePath\n    );\n\n    const files = tsConfig.raw?.files;\n    const include = tsConfig.raw?.include;\n\n    if (Array.isArray(files)) {\n      const match = files.find(\n        (file) =>\n          normalizePath(file, workspaceRoot, projectAbsolutePath) ===\n          normalizedPath\n      );\n\n      if (match) {\n        return true;\n      }\n    }\n\n    // If not matched by `files`, check `include` patterns\n    if (!Array.isArray(include)) {\n      // If no include patterns, TypeScript includes all TS files by default\n      const ext = extname(path);\n      const tsExtensions = ['.ts', '.tsx', '.cts', '.mts'];\n      return tsExtensions.includes(ext);\n    }\n\n    const relativeToProject = relative(projectAbsolutePath, normalizedPath);\n\n    return include.some((pattern) => picomatch(pattern)(relativeToProject));\n  };\n\n  // Check the `.` export if `exports` is defined.\n  const exports = packageJson.exports;\n  if (!exports) {\n    // If any entry point doesn't point to a source file, or if no entry points\n    // are defined (Node.js falls back to `./index.js`), then it's buildable\n    return (\n      packageJsonLegacyEntryPoints.some(\n        (field) => packageJson[field] && !isPathSourceFile(packageJson[field])\n      ) || packageJsonLegacyEntryPoints.every((field) => !packageJson[field])\n    );\n  }\n\n  if (typeof exports === 'string') {\n    return !isPathSourceFile(exports);\n  }\n\n  const isExportsEntryPointingToSource = (\n    value: string | Record<string, string>\n  ): boolean => {\n    if (typeof value === 'string') {\n      return isPathSourceFile(value);\n    }\n\n    if (typeof value === 'object') {\n      // entry point point to a source file if all conditions that are not set\n      // to `null` point to a source file\n      return Object.values(value).every(\n        (subValue) => typeof subValue !== 'string' || isPathSourceFile(subValue)\n      );\n    }\n\n    return false;\n  };\n\n  if ('.' in exports && exports['.'] !== null) {\n    return !isExportsEntryPointingToSource(exports['.']);\n  }\n\n  // If any export is not pointing to a source file, then it's buildable\n  return Object.keys(exports).some(\n    (key) =>\n      key !== '.' &&\n      key !== './package.json' &&\n      !isExportsEntryPointingToSource(exports[key])\n  );\n}\n\nfunction normalizePath(\n  path: string,\n  workspaceRoot: string,\n  projectAbsolutePath: string\n): string {\n  return isAbsolute(path)\n    ? resolve(workspaceRoot, path.startsWith('/') ? path.slice(1) : path)\n    : resolve(projectAbsolutePath, path);\n}\n"],"names":["addBuildAndWatchDepsTargets","isValidPackageJsonBuildConfig","picomatch","workspaceRoot","projectRoot","targets","options","pmc","projectName","projectJsonPath","join","packageJsonPath","existsSync","projectJson","readJsonFile","name","packageJson","nx","buildDepsTargetName","dependsOn","watchDepsTargetName","continuous","command","exec","tsConfig","resolvedProjectPath","isAbsolute","relative","projectAbsolutePath","resolve","outFile","isAnyEntryPointPointingToOutFile","outDir","isAnyEntryPointPointingToOutDir","isAnyEntryPointPointingToNonIncludedFiles","packageJsonLegacyEntryPoints","relativeToProject","startsWith","isPathPointingToOutputFile","path","normalizePath","exports","some","field","every","isExportsEntryPointingToOutFile","value","Object","values","subValue","keys","key","resolvedOutDir","relativePath","isPathInsideOutDir","normalizedPath","isExportsEntryPointingToPathInsideOutDir","isPathSourceFile","files","raw","include","Array","isArray","match","find","file","ext","extname","tsExtensions","includes","pattern","isExportsEntryPointingToSource","slice"],"mappings":";;;;wBAAuD;wBAC5B;0BAC4B;sBAGlC;+BAkBLA;;;eAAAA;;;QAAAA;;;;+BAqCAC;;;eAAAA;;;QAAAA;;;;AArDhB,MAAOC,oBAAoB;AAgBpB,SAASF,4BACdG,aAAqB,EACrBC,WAAmB,EACnBC,OAA4C,EAC5CC,OAAuE,EACvEC,GAA2B;IAE3B,IAAIC;IAEJ,MAAMC,kBAAkBC,IAAAA,UAAI,EAACP,eAAeC,aAAa;IACzD,MAAMO,kBAAkBD,IAAAA,UAAI,EAACP